def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_lists_lines_in_item_order_with_catalogue_names(shop):
    order_id = order(shop, "c2", ("PEN", 4), ("BOOK", 1), ("LAMP", 2)).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 200
    assert response.body == {
        "order_id": order_id,
        "customer_name": "Grace",
        "lines": [
            {"sku": "PEN", "name": "Pen", "quantity": 4},
            {"sku": "BOOK", "name": "Book", "quantity": 1},
            {"sku": "LAMP", "name": "Lamp", "quantity": 2},
        ],
    }


def test_packing_slip_unknown_order_is_404(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_cancelled_order_is_409(shop):
    order_id = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(order_id)
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 409
    assert "error" in response.body


def test_low_stock_lists_products_below_threshold_lowest_first(shop):
    # Shop stock: BOOK 50, LAMP 5, PEN 100. Ties on on_hand break by sku.
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "ABC", "name": "Abc", "unit_price_cents": 100, "on_hand": 2})
    response = shop.fulfilment.handle_low_stock(10)
    assert response.status == 200
    assert response.body == {"products": [
        {"sku": "ABC", "name": "Abc", "on_hand": 2},
        {"sku": "CUP", "name": "Cup", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
    ]}


def test_low_stock_threshold_is_strict(shop):
    # LAMP has exactly 5 on hand, so it is not below a threshold of 5.
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}


def test_low_stock_skips_inactive_products():
    # No controller deactivates products, so build the service directly.
    catalog = InMemoryProductCatalog()
    stock = InMemoryStockRepository()
    catalog.add(Product("OLD", "Old", 100, active=False))
    stock.set("OLD", 0)
    catalog.add(Product("NEW", "New", 100))
    stock.set("NEW", 1)
    service = FulfilmentService(InMemoryOrderRepository(), InMemoryCustomerRepository(), catalog, stock)
    assert [p.sku for p in service.low_stock(10)] == ["NEW"]


def test_low_stock_rejects_invalid_threshold(shop):
    for bad in (-1, "5", 2.5, None, True, False):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400, bad
        assert "error" in response.body


def test_low_stock_zero_threshold_returns_nothing(shop):
    assert shop.fulfilment.handle_low_stock(0).body == {"products": []}

