shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 4})
# Under the line: LAMP (4) and CUP (4). BOOK (48) and PEN (96) are not.
assert shop.fulfilment.handle_fulfilment_summary().body == {
    "open_orders": 3, "units_to_pick": 7, "low_stock_products": 2}

tool_use_result.oldString:
# Shop stock: BOOK 50, LAMP 5, PEN 100. Only LAMP is at or below the line of 5... and it is not
# below it, so no product is low yet.
assert shop.fulfilment.handle_fulfilment_summary().body == {
    "open_orders": 0, "units_to_pick": 0, "low_stock_products": 0}
order(shop, "c1", ("BOOK", 2), ("PEN", 1))
order(shop, "c2", ("PEN", 3))
cancelled = order(shop, "c2", ("BOOK", 7)).body["order_id"]
shop.orders.handle_cancel(cancelled)
# Dropping LAMP to 4 and adding a product with 4 units makes two products under the line.
order(shop, "c1", ("LAMP", 1))
shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 4})
assert shop.fulfilment.handle_fulfilment_summary().body == {
    "open_orders": 3, "units_to_pick": 7, "low_stock_products": 1}

tool_use_result.newString:
# Shop stock: BOOK 50, LAMP 5, PEN 100. LAMP at exactly 5 is not below the line.
assert shop.fulfilment.handle_fulfilment_summary().body == {
    "open_orders": 0, "units_to_pick": 0, "low_stock_products": 0}
order(shop, "c1", ("BOOK", 2), ("PEN", 1))   # open: 3 units
order(shop, "c2", ("PEN", 3))                # open: 3 units
cancelled = order(shop, "c2", ("BOOK", 7)).body["order_id"]
shop.orders.handle_cancel(cancelled)         # cancelled: excluded, stock restored
order(shop, "c1", ("LAMP", 1))               # open: 1 unit; LAMP drops to 4, under the line
shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 4})
# Under the line: LAMP (4) and CUP (4). BOOK (48) and PEN (96) are not.
assert shop.fulfilment.handle_fulfilment_summary().body == {
